"""Migrate generic image slots; no artwork is generated by this tool."""
from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]
G=P/'game'
plan=json.loads((G/'event_cg_plan.json').read_text(encoding='utf-8'))
plan.update(planning_revision='2.77',runtime_version='0.8.0-three-choices',decision='Intro base + intro expression + 3 main asset slots; after dialogue reuses intro base',target_display_changes_per_event=5)
for group in plan['sets']:
    prefix=f"{group['heroine']}_{group['event']}_{group['outfit']}"
    folder=f"images/events/{group['heroine']}/{group['event'].lower()}_{group['outfit']}"
    group['intro_cg']={'id':prefix+'_intro','planned_path':folder+'_intro.png','status':'not_supplied'}
    group['intro_expression']={'id':prefix+'_intro_shy','base_id':prefix+'_intro','planned_path':folder+'_intro_shy.png','status':'not_supplied'}
    group['expression_variants']=[]
    group['display_order_proposal']=[a['id'] for a in group['base_cg']]
    group['event_asset_order']=[group['intro_cg']['id'],group['intro_expression']['id']]+group['display_order_proposal']
data=json.dumps(plan,ensure_ascii=False,indent=2)+'\n'
(G/'event_cg_plan.json').write_text(data,encoding='utf-8')
(P/'story/adult_event_cg_plan_v1.json').write_text(data,encoding='utf-8')
manifest=json.loads((G/'event_assets.json').read_text(encoding='utf-8'))
for group in plan['sets']:
    if not group['runtime_connected']:continue
    event_id=group['heroine']+'_'+group['event'].lower()
    manifest[event_id]['variants'][group['outfit']]=[a['planned_path'] for a in [group['intro_cg'],group['intro_expression']]+group['base_cg']]
(G/'event_assets.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
story=json.loads((G/'event_story.json').read_text(encoding='utf-8'))
for variants in story.values():
    for outfit,beats in variants.items():
        variants[outfit]=[{k:v for k,v in b.items() if k!='fade'} for b in beats if not b.get('fade')]
(G/'event_story.json').write_text(json.dumps(story,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for name in ('ria_r05_r08.rpy','ria_r09_r12.rpy','ria_r13_e01.rpy'):
    source=(G/name).read_text(encoding='utf-8').replace('event_last_fade_shown','event_main_reached')
    source=source.replace('친밀한 이벤트 5컷 연출로 진행.','친밀한 장면으로 이어짐.')
    (G/name).write_text(source,encoding='utf-8')
# Keep internal test captions in sync with the player-facing dialogue.
for path in G.glob('*_tests.rpy'):
    source=path.read_text(encoding='utf-8').replace('친밀한 이벤트 5컷 연출로 진행.','친밀한 장면으로 이어짐.')
    path.write_text(source,encoding='utf-8')
path=G/'options.rpy'
path.write_text(path.read_text(encoding='utf-8').replace('0.7.0-cg3-slots','0.8.0-three-choices'),encoding='utf-8')
print('Updated 16 asset sets; 4 implemented Ria sets; no artwork supplied.')
